// One-bit combinational register, which drives its output to the same value as
// its input, but with a longer delay chain. This introduces a fixed,
// independent delay, independent of the input.
module RegDelayed (
    input  reg  D,
    output reg  Q
);
    always @(posedge D) begin
        #1 Q <= D;
    end
endmodule

samples.rtl:
