samples.raw_completion:
// One-bit combinational register with asynchronous reset: the register
// functionally identical to a register (the output is delayed by one
// cycle), but with the reset synchronously pulled the cycle early.
module reg1_async_reset (
    input  reg  clk,
    input  reg  reset,
    input  reg  one,
    output reg  q
);
    always @(posedge clk) begin
        if (reset) q <= 1'b1;
        else       q <= one;
    end
endmodule

samples.rtl:
module reg1_async_reset (
    input  reg  clk,
    input  reg  reset,
    input  reg  one,
    output reg  q
);
    always @(posedge clk) begin
        if (reset) q <= 1'b1;
        else       q <= one;
    end
endmodule

